style.css:
@-moz-document domain("roblox.com"), domain("www.roblox.com") {
:root {
    /* Replace these with your images */
    --bg-url: "https://i.imgur.com/REPLACE_WITH_YOUR_BACKGROUND.jpg";
    --logo-url: "https://i.imgur.com/REPLACE_WITH_YOUR_SCP_LOGO.png";

    /* Visual controls */
    --overlay-color: rgba(0,0,0,0.65);   /* darkness over the whole page */
    --fog-url: "https://i.imgur.com/REPLACE_WITH_FOG_TILE.png"; /* subtle fog tile or gradient */
    --fog-opacity: 0.12;
    --static-opacity: 0.03;
    --logo-opacity: 0.08;
    --accent-glow: 0 0 18px rgba(180,0,0,0.25);
  }

  /* Base background — fix, cover */
  html, body, #container, .container-main, .content {
    background-image: linear-gradient(rgba(0,0,0,0.12), rgba(0,0,0,0.32)), url(var(--bg-url));
    background-size: cover;
    background-position: center center;
    background-attachment: fixed;
    background-repeat: no-repeat;
    color: #e6e6e6 !important;
    transition: background 300ms ease;
  }

  /* Dark overlay to make the site readable */
  html:before {
    content: "";
    position: fixed;
    left: 0; right: 0; top: 0; bottom: 0;
    background: var(--overlay-color);
    pointer-events: none;
    z-index: 999998;
  }

  /* Subtle moving fog using a tiled/semi-transparent PNG or CSS gradient */
  html:after {
    content: "";
    position: fixed;
    left: -25%; right: -25%; top: -25%; bottom: -25%;
    background-image: url(var(--fog-url));
    background-repeat: repeat;
    opacity: var(--fog-opacity);
    filter: blur(6px) saturate(0.7);
    transform: translateZ(0);
    animation: fog-move 60s linear infinite;
    pointer-events: none;
    z-index: 999997;
    mix-blend-mode: screen;
  }

  @keyframes fog-move {
    from { background-position: 0% 0%; }
    to   { background-position: 100% 50%; }
  }

  /* Very faint static/grain to make it eerie */
  .rbx-static-overlay {
    pointer-events: none;
    position: fixed;
    z-index: 999999;
    inset: 0;
    background-image: radial-gradient(rgba(255,255,255,var(--static-opacity)) 1px, transparent 1px);
    background-size: 2px 2px;
    mix-blend-mode: overlay;
    opacity: 1;
  }

  /* Add the static element into the page (works in userstyle by injecting a pseudo element on body) */
  body > .rbx-static-inject { display: none; } /* fallback if injection blocked */
  body::marker { } /* noop to avoid linter warnings */

  /* SCP watermark logo (centered, subtle) */
  body::before {
    content: "";
    position: fixed;
    left: 50%;
    top: 12%;
    transform: translateX(-50%);
    width: 340px;
    height: 340px;
    background-image: url(var(--logo-url));
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    opacity: var(--logo-opacity);
    filter: grayscale(100%) contrast(0.9) blur(0px);
    pointer-events: none;
    z-index: 999996;
    mix-blend-mode: soft-light;
  }

  /* Make headers, usernames, and key text slightly eerie */
  .navbar, .rbx-header, .top-nav, h1, h2, h3, .badge-text, .text-label {
    color: #e9e9e9 !important;
    text-shadow: 0 1px 0 rgba(0,0,0,0.8), 0 0 6px rgba(0,0,0,0.25);
  }

  /* Links (muted, with red hover glow) */
  a, .text-link, .link {
    color: #cfcfcf !important;
    transition: color 150ms ease, text-shadow 150ms ease;
  }
  a:hover, .text-link:hover, .link:hover {
    color: #ffdcdc !important;
    text-shadow: var(--accent-glow);
  }

  /* Cards, panels — dark glass effect so content is readable */
  .card, .panel, .rbx-body, .game-card, .section {
    background-color: rgba(6,6,6,0.45) !important;
    border: 1px solid rgba(255,255,255,0.04) !important;
    backdrop-filter: blur(6px) saturate(0.8);
    box-shadow: 0 6px 18px rgba(0,0,0,0.6);
  }

  /* Buttons — subtle red accent */
  .btn, button, .btn-primary, .rbx-button {
    background-image: linear-gradient(180deg, rgba(255,255,255,0.02), rgba(0,0,0,0.12));
    border: 1px solid rgba(255,255,255,0.04);
    color: #eee !important;
  }
  .btn:hover, .rbx-button:hover {
    box-shadow: var(--accent-glow);
  }

  /* Tiny UI tweaks: dim icons that would stand out too bright */
  img, svg, .icon {
    filter: brightness(0.95) contrast(0.95);
  }

  /* Keep modals, dropdowns usable above overlays */
  .modal, .modal-root, .modal-dialog, .dropdown-content {
    z-index: 1000001 !important;
  }

  /* Respect mobile layouts */
  @media (max-width: 600px) {
    body::before { width: 220px; height: 220px; top: 6%; }
  }

  /* Accessibility: make sure focus outlines still visible */
  :focus {
    outline: 2px dashed rgba(200,0,0,0.35) !important;
    outline-offset: 2px;
  }

  /* Optional: hide distracting Roblox background animations if present */
  .home-background-animation, .site-background-anim {
    display: none !important;
  }
}
